mapper.sql:
SELECT , (u.skin_id IS NOT NULL) AS owned
FROM space_skin s
LEFT JOIN user_space_skin u ON u.skin_id = s.skin_id AND u.user_id = #{userId,jdbcType=BIGINT}

mapper.update:
UPDATE space_skin SET name = #{edit.name}, coin_price = #{edit.price}, sort_order = #{edit.sortOrder},
    listed = #{edit.listed}, version = version + 1
WHERE skin_id = #{id} AND version = #{edit.version}
